<?php
require_once __DIR__ . '/../config/app.php'; require_customer();
if(!is_post())redirect('orders.php');verify_csrf();$orderId=(int)($_POST['order_id']??0);$pdo=db();$pdo->beginTransaction();
try{$s=$pdo->prepare('SELECT * FROM orders WHERE id=? AND user_id=? FOR UPDATE');$s->execute([$orderId,current_user()['id']]);$order=$s->fetch();if(!$order||$order['order_status']!=='pending'||!in_array($order['payment_status'],['unpaid','rejected'],true))throw new RuntimeException('Pesanan ini tidak dapat dibatalkan sendiri. Hubungi admin jika pembayaran sudah dikirim.');$items=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$items->execute([$orderId]);foreach($items->fetchAll() as $item){if(!$item['product_id'])continue;$p=$pdo->prepare('SELECT stock FROM products WHERE id=? FOR UPDATE');$p->execute([$item['product_id']]);$before=(int)$p->fetchColumn();$after=$before+(int)$item['quantity'];$pdo->prepare('UPDATE products SET stock=? WHERE id=?')->execute([$after,$item['product_id']]);$pdo->prepare("INSERT INTO stock_movements(product_id,user_id,order_id,movement_type,quantity,stock_before,stock_after,notes) VALUES(?,?,?,'return',?,?,?,'Pembatalan oleh pembeli')")->execute([$item['product_id'],current_user()['id'],$orderId,$item['quantity'],$before,$after]);}$pdo->prepare("UPDATE orders SET order_status='cancelled',stock_restored_at=NOW() WHERE id=?")->execute([$orderId]);$pdo->prepare("INSERT INTO order_status_histories(order_id,changed_by,old_status,new_status,notes) VALUES(?,?,'pending','cancelled','Dibatalkan pembeli')")->execute([$orderId,current_user()['id']]);$pdo->commit();notify_order_status_changed($orderId);flash('success','Pesanan dibatalkan dan stok telah dikembalikan.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger',$e->getMessage());}redirect('order-detail.php?id='.$orderId);
